// Generated by tools/doxy2mdx/generate_examples.py from doc/api_registry.json.
import data from '../data/knowledge.json';

export interface DocLink {
    label: string;
    url: string;
}

export interface ApiLink {
    name: string;
    url: string;
    methods: { name: string; url: string }[];
}

export interface TopicExample {
    name: string;
    title: string;
    brief: string;
    url: string;
    start: boolean;
}

export interface Topic {
    id: string;
    title: string;
    summary: string;
    manual: DocLink[];
    tools: DocLink[];
    api: ApiLink[];
    examples: TopicExample[];
}

export interface Example {
    name: string;
    title: string;
    brief: string;
    /** First figure of the example's last run, empty when it draws none. */
    thumbnail: string;
    url: string;
    library: string;
    libraries: string[];
    tasks: string[];
    modalities: string[];
    level: string;
    topics: string[];
}

export interface Facets {
    tasks: Record<string, string>;
    modalities: Record<string, string>;
    levels: Record<string, string>;
}

export const facets = data.facets as Facets;
export const libraries = data.libraries as Record<string, string>;
export const examples = data.examples as Example[];
export const topics = data.topics as Topic[];

export function topicById(id: string): Topic | undefined {
    return topics.find((t) => t.id === id);
}

export function exampleByName(name: string): Example | undefined {
    return examples.find((e) => e.name === name);
}
